import{_ as t,o as a,c as n,a5 as i}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"Learning State Template","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/learning-state.en.md","filePath":"public/downloads/worksheets/learning-state.en.md","lastUpdated":1795488252000}'),r={name:"public/downloads/worksheets/learning-state.en.md"};function o(s,e,l,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="learning-state-template" tabindex="-1">Learning State Template <a class="header-anchor" href="#learning-state-template" aria-label="Permalink to &quot;Learning State Template&quot;">​</a></h1><p>Copy this into a private note. It is a cross-session source of truth, not a performance diary. Do not include passwords, government IDs, exact addresses, sensitive health data, or third-party information without permission.</p><h2 id="if-you-only-have-five-minutes-today" tabindex="-1">If you only have five minutes today <a class="header-anchor" href="#if-you-only-have-five-minutes-today" aria-label="Permalink to &quot;If you only have five minutes today&quot;">​</a></h2><p>Do not fill the whole form first. Copy the minimum version below and do the action; expand it into the full state file only when you need to resume across sessions, hand work over, or review a cycle.</p><h3 id="learning-state-—-minimum" tabindex="-1">Learning State — minimum <a class="header-anchor" href="#learning-state-—-minimum" aria-label="Permalink to &quot;Learning State — minimum&quot;">​</a></h3><p>Date: YYYY-MM-DD<br> The real problem I am handling:<br> Evidence I already have:<br> The smallest action I can finish today:<br> Evidence I will save when it is done:<br> What I will not upload or publish:</p><p>The minimum is complete when a future version of you can understand the problem, current evidence, next action, and boundary. It is not a full plan or a substitute for an independent retest. It is a way to let action happen first.</p><h3 id="learning-state" tabindex="-1">Learning State <a class="header-anchor" href="#learning-state" aria-label="Permalink to &quot;Learning State&quot;">​</a></h3><p>State version: v1<br> Updated: YYYY-MM-DD<br> Owner:<br> Primary file location:</p><h4 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h4><ul><li>Real context:</li><li>Current main task:</li><li>12-week outcome:</li><li>This week&#39;s focus:</li><li>Acceptance criteria:</li><li>Deadline:</li></ul><h4 id="constraints-and-boundaries" tabindex="-1">Constraints and Boundaries <a class="header-anchor" href="#constraints-and-boundaries" aria-label="Permalink to &quot;Constraints and Boundaries&quot;">​</a></h4><ul><li>Weekly time/energy available:</li><li>Materials and tools allowed:</li><li>Content that must not be uploaded or published:</li><li>AI may assist with:</li><li>A person must confirm:</li></ul><h4 id="current-level-and-baseline" tabindex="-1">Current Level and Baseline <a class="header-anchor" href="#current-level-and-baseline" aria-label="Permalink to &quot;Current Level and Baseline&quot;">​</a></h4><ul><li>I can currently:</li><li>Baseline sample:</li><li>Latest score/feedback:</li></ul><table tabindex="0"><thead><tr><th>Sample</th><th>Conditions</th><th>Location</th><th>Date</th><th>What it does not show yet</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h4 id="completed" tabindex="-1">Completed <a class="header-anchor" href="#completed" aria-label="Permalink to &quot;Completed&quot;">​</a></h4><ul><li>[date] task — output/evidence location — result/next step</li></ul><h4 id="errors-risks-and-knowledge-gaps" tabindex="-1">Errors, Risks, and Knowledge Gaps <a class="header-anchor" href="#errors-risks-and-knowledge-gaps" aria-label="Permalink to &quot;Errors, Risks, and Knowledge Gaps&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Error/risk</th><th>Evidence</th><th>Likely cause/confidence</th><th>Next treatment and stop condition</th></tr></thead></table><h4 id="methods-that-worked" tabindex="-1">Methods That Worked <a class="header-anchor" href="#methods-that-worked" aria-label="Permalink to &quot;Methods That Worked&quot;">​</a></h4><ul><li>Method — conditions — evidence</li></ul><h4 id="hypotheses-to-test" tabindex="-1">Hypotheses to Test <a class="header-anchor" href="#hypotheses-to-test" aria-label="Permalink to &quot;Hypotheses to Test&quot;">​</a></h4><ul><li>Hypothesis — counterexample — next test — deadline</li></ul><h4 id="latest-handover" tabindex="-1">Latest Handover <a class="header-anchor" href="#latest-handover" aria-label="Permalink to &quot;Latest Handover&quot;">​</a></h4><ul><li>Completed and evidence:</li><li>Facts still unconfirmed:</li><li>Open decisions:</li><li>Cost/rework so far:</li><li>First action when reopening:</li><li>People to notify or consult:</li></ul><h4 id="next-action" tabindex="-1">Next Action <a class="header-anchor" href="#next-action" aria-label="Permalink to &quot;Next Action&quot;">​</a></h4><ol><li>Smallest next task:</li><li>Expected time:</li><li>Material needed:</li><li>Evidence to save:</li><li>Next review date:</li></ol><h2 id="cross-session-recovery-prompt" tabindex="-1">Cross-session Recovery Prompt <a class="header-anchor" href="#cross-session-recovery-prompt" aria-label="Permalink to &quot;Cross-session Recovery Prompt&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Below is my learning-state file. In no more than six bullets, restate the state version, goal, current evidence, main errors, boundaries, and next action. Flag conflicts or missing information; do not pretend to remember another chat or invent facts absent from the file. Design one exercise only for the “smallest next task”: let me answer first, then give feedback against the acceptance criteria. Do not provide a complete answer unless I ask. Finish with five paste-ready updates: completed, evidence, errors/risks, handover, next action.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste Learning State]</span></span></code></pre></div><p>An AI summary is not the source of truth. Resume from the file, saved work, sources, and version number; after a weekly review, update the <a href="https://byoungd.github.io/up/en/templates/weekly-review" target="_blank" rel="noreferrer">Weekly Review</a>, <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain</a>, and <a href="https://byoungd.github.io/up/en/templates/90-day-cycle" target="_blank" rel="noreferrer">90-Day Cycle Map</a> by their separate jobs instead of copying the same record.</p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/learning-state" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-10-06. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>`,33)])])}const m=t(r,[["render",o]]);export{p as __pageData,m as default};
